const api=async(p:string,o?:RequestInit)=>{const r=await fetch('/api'+p,{credentials:'include',headers:{'Content-Type':'application/json'},...o});if(!r.ok)throw new Error((await r.json().catch(()=>({}))).error||'Something went wrong');return r.status===204?null:r.json()};
const fmt=(d?:string)=>d?new Intl.DateTimeFormat('en',{month:'short',day:'numeric'}).format(new Date(d)):'—';const stage=(s:string)=>s.replaceAll('_',' ').replace(/\b\w/g,(x:string)=>x.toUpperCase());
