function FirmInterviewContext({applications}:{applications:any[]}){const withInterviews=applications.filter(x=>x.interviews?.length);return withInterviews.length?<section className="panel activity"><div className="panel-head"><div><h2>Firm interview activity</h2><p>Upcoming and historical interviews, grouped with their firm, role, and target office.</p></div></div>{withInterviews.flatMap(app=>app.interviews.map((item:any)=><div className="task-line" key={item.id}><div><strong>{app.opportunity.company.name} — {app.opportunity.roleTitle}</strong><p>{stage(item.interviewRound)} · {interviewWhen(item.date,item.timezone)}{app.opportunity.office?` · ${app.opportunity.office.city}`:''}</p></div><Badge tone={item.completedAt?'gray':'blue'}>{item.completedAt?stage(item.outcome):'Scheduled'}</Badge></div>))}</section>:null}
