function Timeline({data}:{data:any}){const items=[...(data?.deadlines||[]).map((x:any)=>({date:x.applicationDeadline,type:'Application deadline',title:`${x.company.name} — ${x.roleTitle}`,tone:'rose'})),...(data?.interviews||[]).map((x:any)=>({date:x.date,type:'Interview',title:`${x.application.opportunity.company.name} · ${x.interviewRound}`,tone:'blue'})),...(data?.tasks||[]).map((x:any)=>({date:x.dueDate,type:'Task',title:x.title,tone:'orange'})),...(data?.followups||[]).map((x:any)=>({date:x.nextFollowUpDate,type:'Follow-up',title:`${x.firstName} ${x.lastName}`,tone:'green'}))].filter(x=>x.date).sort((a,b)=>+new Date(a.date)-+new Date(b.date));return <><Header title="Timeline" desc="Everything that needs your attention, in one view."/><div className="timeline">{items.map((x:any,i)=><div className="timeline-row" key={i}><div className="timeline-date"><b>{fmt(x.date)}</b><span>{new Intl.DateTimeFormat('en',{weekday:'short'}).format(new Date(x.date))}</span></div><i className={x.tone}/><article><Badge tone={x.tone}>{x.type}</Badge><h3>{x.title}</h3></article></div>)}</div></>}
